<script setup>
import {computed,ref,watch} from 'vue';
import NativeOperationStatus from './NativeOperationStatus.vue';
import {nativeItems,nativeValue} from '../bot-native-data.js';
const props=defineProps({ui:{type:Object,required:true},bot:{type:Object,required:true},draft:{type:Object,required:true},bots:{type:Array,required:true},enabled:Boolean,configBusy:Boolean});const emit=defineEmits(['save-config']);
const mode=ref('message'),targets=ref([]),content=ref(''),groupId=ref(''),sourceActionId=ref('');
const state=computed(()=>props.ui.resource('collaboration'));
const groups=computed(()=>props.ui.resource('groups')),groupDetail=computed(()=>props.ui.resource('groupDetail')),groupRows=computed(()=>nativeItems(groups.value.data,['items'])),groupData=computed(()=>nativeValue(groupDetail.value.data)),groupEvents=computed(()=>groupData.value?.events?.events||[]);
const available=computed(()=>props.bots.filter(item=>item.workspace===props.ui.state.workspace&&item.id!==props.bot.id&&item.kind!=='creator'));
const rows=computed(()=>nativeItems(state.value.data,['collaborations','runs','items']));
const result=computed(()=>state.value.result?.nativeOperation?.data||state.value.result?.result?.nativeOperation?.data||state.value.result);
async function submit(){const allowed=new Set(available.value.map(item=>item.id));const selected=targets.value.filter(id=>allowed.has(id));if(selected.length!==targets.value.length)return;await props.ui.submit('collaboration',mode.value,{targetEmployeeIds:selected,content:content.value,...(groupId.value?{groupId:groupId.value}:{}),...(sourceActionId.value?{sourceActionId:sourceActionId.value}:{})});}
function authorize(){props.draft.config.collaboration={enabled:true,targetEmployeeIds:[...targets.value]};}
watch(()=>[props.ui.state.workspace,props.bot.id],()=>{mode.value='message';targets.value=[];content.value='';groupId.value='';sourceActionId.value='';},{immediate:true});
</script>
<template>
  <div class="native-workspace"><section class="native-section" aria-label="Bot 协作">
    <div class="native-toolbar"><div><h3>伙伴协作</h3><p class="native-help">发送、群组 @ 或委派都选择当前工作区的精确员工 ID。目标员工仍独立核对启用、权限和运行状态。</p></div><button class="bot-button" :disabled="!enabled||state.loading" @click="ui.read('collaboration')">读取协作进度</button></div>
    <div class="native-subtabs"><button :class="{selected:mode==='message'}" @click="mode='message'">Bot 消息</button><button :class="{selected:mode==='group'}" @click="mode='group'">群组 / @提及</button><button :class="{selected:mode==='delegate'}" @click="mode='delegate'">委派工作</button></div>
    <p class="native-help">{{bot.config.collaboration?.enabled?'此 Bot 已保存协作授权':'先选择明确伙伴并加入配置，再保存、检查和启用 Bot。协作还需 execute 权限。'}}</p>
    <div class="native-fields"><label>选择伙伴</label><label v-for="item in available" :key="item.id" class="inline-check"><input v-model="targets" type="checkbox" :value="item.id"/>{{item.employee.name}} · {{item.control_state}} · {{item.id}}</label><p v-if="!available.length" class="native-empty">当前工作区没有其他可选择的 Hermes 员工。</p><label>消息或委派内容<textarea v-model="content" rows="5" placeholder="任务目标、需要协作的内容与结果要求"/></label><label v-if="mode==='group'">原生 Group ID（首次可留空）<input v-model="groupId"/></label><label v-if="mode==='delegate'">来源 Action ID（可选）<input v-model="sourceActionId"/></label></div>
    <div class="native-actions"><button class="bot-button" :disabled="!enabled||configBusy||!targets.length||targets.length>5" @click="authorize">将所选伙伴加入协作配置草稿</button><button class="bot-button" :disabled="!enabled||configBusy" @click="emit('save-config')">保存全部配置并读回</button><button class="bot-button primary" :disabled="!enabled||bot.control_state!=='active'||ui.blocked()||!bot.config.collaboration?.enabled||bot.config.permissions.mode!=='execute'||!targets.length||targets.length>5||!content.trim()" @click="submit">{{mode==='delegate'?'提交精确目标委派':mode==='group'?'发送给所选群组伙伴':'发送给所选伙伴'}}</button></div><NativeOperationStatus :state="state" @poll="ui.poll('collaboration')" @recover="ui.recover('collaboration')"/>
    <p class="native-help">受理协作与目标完成分开；未知发送不会换请求标识重发。当前员工、目标、主聊天和父子执行关联以服务器回执为准。</p>
    <div class="native-list"><article v-for="item in rows" :key="item.id||item.envelopeId" class="native-list-row"><div><strong>{{item.collaborationRole==='target'?'目标工作':'源 Bot 派发'}} · {{item.payload?.collaboration?.mode||item.mode||item.type||'协作执行'}} · {{item.status||'等待回执'}}</strong><small>{{item.id||item.envelopeId}} · {{item.payload?.employeeId||item.employeeId||bot.id}}</small><p>{{item.result?.output||item.result?.summary||item.error||''}}</p><small v-if="item.parentActionId||item.payload?.collaboration?.sourceActionId">来源执行：{{item.parentActionId||item.payload.collaboration.sourceActionId}}</small><small v-if="item.targetEmployeeIds">目标：{{item.targetEmployeeIds.join('、')}}</small></div></article></div>
    <p v-if="result?.summary||result?.output" class="native-record">{{result.summary||result.output}}</p>
    <div class="native-toolbar"><div><h3>原生群组记录</h3><p class="native-help">群组成员、事件和待执行计划来自当前 Bot 的原生 room 数据库。</p></div><button class="bot-button" :disabled="!enabled||groups.loading" @click="ui.read('groups')">读取原生群组</button></div>
    <div class="native-list"><article v-for="room in groupRows" :key="room.room_id" class="native-list-row"><div><strong>{{room.name||room.room_id}}</strong><small>{{room.room_id}}</small></div><div class="native-actions"><button class="bot-button" :disabled="groupDetail.loading" @click="ui.read('groupDetail',{groupId:room.room_id})">查看群组事件</button><button class="bot-button" :disabled="!enabled||ui.blocked()||bot.control_state!=='active'||bot.config.permissions.mode!=='execute'" @click="ui.submit('groups','step',{groupId:room.room_id})">推进此群组一次</button></div></article></div>
    <div v-if="groupData?.room" class="native-record"><strong>{{groupData.room.name||groupData.room.room_id}}</strong><p v-for="event in groupEvents" :key="event.event_id||event.id">{{event.kind}} · {{event.payload?.text||event.payload?.result||''}}</p><details><summary>原生群组决策与计划</summary><pre>{{JSON.stringify({decision:groupData.decision,plan:groupData.plan},null,2)}}</pre></details></div><NativeOperationStatus :state="groups" @poll="ui.poll('groups')" @recover="ui.recover('groups')"/><NativeOperationStatus :state="groupDetail"/>
  </section></div>
</template>
